// A webhook törzse a `body` alatt jön. Mindent ellenőrzünk, mert ide
// bárki küldhet bármit — az app nem az egyetlen, aki elérheti.
const body = $input.first().json.body ?? {};

const text = typeof body.ingredientsText === 'string' ? body.ingredientsText.trim() : '';
const code = typeof body.code === 'string' ? body.code : '';
const lang = typeof body.lang === 'string' ? body.lang : null;

// Felső korlát: egy összetevőlista sosem ilyen hosszú. Ami hosszabb, az vagy
// hiba, vagy valaki a modellt akarja terhelni a te kvótád terhére.
const MAX = 2000;

if (text.length === 0) {
  return [{ json: { ok: false, code, status: 'kihagyva', indok: 'ures_szoveg', translatedText: null } }];
}
if (text.length > MAX) {
  return [{ json: { ok: false, code, status: 'kihagyva', indok: 'tul_hosszu', translatedText: null } }];
}

return [{ json: { ok: true, code, lang, text } }];

// Az eredeti kérés adatait a validáló node-ból vesszük vissza — a lánc
// kimenete csak a lefordított szöveget tartalmazza.
const eredeti = $('Ellenőrzés').first().json;
const nyers = ($input.first().json.text ?? '').trim();

// A modellt megkértük, hogy pontosan ezt írja, ha nem boldogul. Ezt komolyan
// vesszük: inkább ne fordítsunk, mint rosszul.
const sikertelen = nyers.length === 0 || nyers.includes('NEM_FORDITHATO');

/** Egy megnevezett sor értéke a válaszból. A `-` jelentése: nincs ilyen rész. */
function sor(kulcs) {
  const talalat = nyers.match(new RegExp('^' + kulcs + ':\\s*(.*)$', 'mi'));
  const ertek = (talalat?.[1] ?? '').trim();
  return ertek.length === 0 || ertek === '-' ? null : ertek;
}

const osszetevok = sikertelen ? null : sor('OSSZETEVOK');
const nyomokban = sikertelen ? null : sor('NYOMOKBAN');

// Ha a modell nem tartotta a formátumot, NEM találgatunk: inkább nincs
// fordítás, mint olyan, amiről nem tudjuk, tartalmaz-e vagy tartalmazhat.
const formatumHiba = !sikertelen && osszetevok === null;
const rendben = !sikertelen && !formatumHiba;

return [{
  json: {
    ok: rendben,
    code: eredeti.code,
    status: sikertelen ? 'nem_fordithato' : formatumHiba ? 'rossz_formatum' : 'ok',
    sourceLang: eredeti.lang,
    // A `translatedBy` szándékosan benne van: az appnak tudnia kell, hogy ez
    // gépi fordítás, és a felületen jelölnie is kell.
    translatedBy: 'ai',
    translatedText: rendben ? osszetevok : null,
    translatedTraces: rendben ? nyomokban : null,
    translatedAt: new Date().toISOString(),
  },
}];
